import { cp, mkdir, access } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Resolve from this file so the script works regardless of the current working directory.
const rootDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const publicDir = path.join(rootDir, 'public');
const distDir = path.join(rootDir, 'dist');
await mkdir(distDir, { recursive: true });

/* sitemap.xml, robots.txt and _headers are generated by scripts/generate-seo.mjs. */
const files = [
  'favicon.ico',
  'favicon.svg',
  'favicon.png',
  'favicon-16x16.png',
  'favicon-32x32.png',
  'favicon-48x48.png',
  'favicon-180x180.png',
  'favicon-192x192.png',
  'favicon-512x512.png',
  'site.webmanifest',
  'assets/krixo-logo.png'
];
for (const file of files) {
  const source = path.join(publicDir, file);
  const target = path.join(distDir, file);
  try {
    await access(source);
    await mkdir(path.dirname(target), { recursive: true });
    await cp(source, target, { force: true });
  } catch {
    console.warn(`[copy-static] WARNING: required file is missing: ${source}`);
  }
}

/* Tesseract fetches these worker, WASM and language files at runtime. */
const directories = ['assets/tesseract'];
for (const dir of directories) {
  const source = path.join(publicDir, dir);
  const target = path.join(distDir, dir);
  try {
    await access(source);
    await cp(source, target, { recursive: true, force: true });
  } catch {
    console.warn(`[copy-static] WARNING: required directory is missing: ${source}`);
  }
}
